// The Q2 2026 Quarterly Report.
//
// Q2 is not generated by the reporting service (the pipeline first ran after the quarter closed, so a
// generated report for it is empty). It is a fixed snapshot, built from the ZMM065 July 2026 extracts and
// the LIS S031 history, shown as a report in its own right next to the generated ones.
//
// This file is the logic around that snapshot -- filtering, paging, the figures a card shows, the CSV.
// The data is loaded lazily (see loadQuarterlySnapshot) so its ~650 KB never reaches a page that does not
// open the report.

export const SNAPSHOT_QUARTER = "Q2 2026"

/** Shown on the landing card in place of "Generated <date>". */
export const SNAPSHOT_CAPTION = "ZMM065 snapshot, July 2026"

export interface SnapshotMaterial {
  matnr: string
  desc: string
  plant: string
  circuit: string
  crit: string
  pattern: string
  risk: string
  stock: number
  uom: string
  lt: number
  ss_cur: number
  ss_rec: number
  rop_cur: number
  rop_rec: number
  max_cur: number
  max_rec: number
  price: number
  wc: number
  status: string
}

export interface QuarterlySnapshot {
  quarter: string
  period: string
  snapshot: string
  plants: { code: number; name: string }[]
  inscope: number
  recs: number
  risk_recs: Record<string, number>
  status: Record<string, number>
  excess_n: number
  excess_val: number
  wc_recs: number
  wc_inscope: number
  inv_value: number
  ss_maintained: number
  rop_maintained: number
  lt_median: number
  sap_touched: number
  cd_coverage: string
  trend: { m: string; v: number }[]
  fa: { m: string; a: number; f: number }[]
  materials: SnapshotMaterial[]
}

/** Loaded on demand: a separate chunk, fetched only when the Q2 report is opened. */
export async function loadQuarterlySnapshot(): Promise<QuarterlySnapshot> {
  const data = await import("@/features/initiative-7/data/quarterly-q2-2026.json")
  return data.default as unknown as QuarterlySnapshot
}

// --- Recommendation status ---------------------------------------------------------------------------

/** The statuses the chart always lists, in this order. */
export const STATUS_ORDER = ["Pending Review", "Approved", "Implemented", "Returned", "Rejected"] as const
export type SnapshotStatus = (typeof STATUS_ORDER)[number]

/**
 * What the status chart shows: Pending Review as counted, every other status at 0. Nothing in Q2 has been
 * approved, implemented, returned or rejected yet, so those are 0 -- listed, not left out.
 */
export function displayStatusCounts(raw: Record<string, number>): { status: SnapshotStatus; count: number }[] {
  return STATUS_ORDER.map((status) => ({
    status,
    count: status === "Pending Review" ? (raw["Pending Review"] ?? 0) : 0,
  }))
}

// --- Stockout risk -----------------------------------------------------------------------------------

export const RISK_ORDER = ["Critical", "High", "Medium", "Low"] as const

export function riskDistribution(risk: Record<string, number>): { level: string; count: number; share: number }[] {
  const total = RISK_ORDER.reduce((sum, level) => sum + (risk[level] ?? 0), 0)
  return RISK_ORDER.map((level) => {
    const count = risk[level] ?? 0
    return { level, count, share: total === 0 ? 0 : (count / total) * 100 }
  })
}

// --- SAP adoption ------------------------------------------------------------------------------------

/** No recommendation has been applied in SAP, so every figure is 0. */
export const ADOPTION_ZERO = [
  { label: "Adopted", count: 0 },
  { label: "Partial", count: 0 },
  { label: "Not adopted", count: 0 },
] as const

// --- Filtering and paging ----------------------------------------------------------------------------

export interface SnapshotFilter {
  query: string
  /** A plant name, or "" for all plants. */
  plant: string
  /** A stockout-risk level, set by clicking the risk chart. "" for all. */
  risk: string
  /** A recommendation status, set by clicking the status chart. "" for all. */
  status: string
}

export const EMPTY_FILTER: SnapshotFilter = { query: "", plant: "", risk: "", status: "" }

export function filterMaterials(rows: SnapshotMaterial[], filter: SnapshotFilter): SnapshotMaterial[] {
  const query = filter.query.trim().toLowerCase()
  return rows.filter(
    (row) =>
      (!filter.plant || row.plant === filter.plant) &&
      (!filter.risk || row.risk === filter.risk) &&
      (!filter.status || row.status === filter.status) &&
      (!query || row.desc.toLowerCase().includes(query) || row.matnr.includes(query)),
  )
}

/** Clicking the segment that is already selected clears it; clicking another switches to it. */
export function toggled(current: string, clicked: string): string {
  return current === clicked ? "" : clicked
}

export function pageOf<T>(rows: T[], page: number, pageSize: number): T[] {
  const start = (page - 1) * pageSize
  return rows.slice(start, start + pageSize)
}

export function pageCount(total: number, pageSize: number): number {
  return Math.max(1, Math.ceil(total / pageSize))
}

// --- Current vs recommended -------------------------------------------------------------------------

export interface ParamRow {
  key: "ss" | "rop" | "max"
  label: string
  hint: string
  current: number
  recommended: number
  delta: number
}

const PARAMS: { key: ParamRow["key"]; label: string; hint: string }[] = [
  { key: "ss", label: "Safety stock", hint: "demand buffer" },
  { key: "rop", label: "Reorder point", hint: "when to raise a PO" },
  { key: "max", label: "Maximum stock", hint: "ceiling to hold" },
]

/** Mean current (SAP) and recommended value over the rows in view. No rows gives zeros, not NaN. */
export function meanParams(rows: SnapshotMaterial[]): ParamRow[] {
  const n = rows.length || 1
  return PARAMS.map(({ key, label, hint }) => {
    const current = rows.reduce((sum, r) => sum + r[`${key}_cur` as const], 0) / n
    const recommended = rows.reduce((sum, r) => sum + r[`${key}_rec` as const], 0) / n
    return { key, label, hint, current, recommended, delta: recommended - current }
  })
}

// --- Formatting --------------------------------------------------------------------------------------

/** "R 32.59M", "R 94 954", "–R 1.30M". Negative amounts carry a leading en dash. */
export function formatZar(value: number): string {
  const abs = Math.abs(value)
  const sign = value < 0 ? "–" : ""
  if (abs >= 1e6) return `${sign}R ${(abs / 1e6).toFixed(2)}M`
  if (abs >= 1e3) return `${sign}R ${Math.round(abs).toLocaleString("en-ZA")}`
  return `${sign}R ${Math.round(abs)}`
}

export function formatPercent(part: number, whole: number, decimals = 1): string {
  return whole === 0 ? "0.0%" : `${((part / whole) * 100).toFixed(decimals)}%`
}

// --- CSV ---------------------------------------------------------------------------------------------

const CSV_COLUMNS: { key: keyof SnapshotMaterial; header: string }[] = [
  { key: "matnr", header: "Material" },
  { key: "desc", header: "Description" },
  { key: "plant", header: "Plant" },
  { key: "circuit", header: "Circuit" },
  { key: "crit", header: "Criticality" },
  { key: "pattern", header: "Demand pattern" },
  { key: "risk", header: "Stockout risk" },
  { key: "stock", header: "Stock on hand" },
  { key: "uom", header: "UoM" },
  { key: "lt", header: "Lead time (days)" },
  { key: "ss_cur", header: "Safety stock (SAP)" },
  { key: "ss_rec", header: "Safety stock (I07)" },
  { key: "rop_cur", header: "ROP (SAP)" },
  { key: "rop_rec", header: "ROP (I07)" },
  { key: "max_cur", header: "Max stock (SAP)" },
  { key: "max_rec", header: "Max stock (I07)" },
  { key: "price", header: "Unit price (ZAR)" },
  { key: "wc", header: "Working capital delta (ZAR)" },
  { key: "status", header: "Approval status" },
]

const csvCell = (value: unknown) => `"${String(value).replace(/"/g, '""')}"`

/** The rows in view as CSV text, with the header row first. */
export function materialsCsv(rows: SnapshotMaterial[]): string {
  const head = CSV_COLUMNS.map((c) => csvCell(c.header)).join(",")
  const body = rows.map((row) => CSV_COLUMNS.map((c) => csvCell(row[c.key])).join(","))
  return [head, ...body].join("\n")
}

export function csvFileName(quarter: string): string {
  return `I07_quarterly_detail_${quarter.replace(" ", "_")}.csv`
}

// --- Which quarters the landing grid offers ----------------------------------------------------------

/** Quarters kept off the landing grid. Q3 2026's generated report is not shown. */
export const HIDDEN_QUARTERS: readonly string[] = ["Q3 2026"]

/**
 * The generated reports' quarters plus the Q2 snapshot, newest first, without the hidden ones. The snapshot is
 * always offered: it is not generated, so it is not in the list the backend returns.
 */
export function landingQuarters(generated: string[]): string[] {
  const key = (quarter: string) => {
    const [q, year] = quarter.replace("Q", "").split(" ")
    return Number(year) * 10 + Number(q)
  }
  return Array.from(new Set([...generated, SNAPSHOT_QUARTER]))
    .filter((quarter) => !HIDDEN_QUARTERS.includes(quarter))
    .sort((a, b) => key(b) - key(a))
}
